from pathlib import Path
import json
B=Path('astrafinalplan/implementation/batch04')
for n in range(62,67):
 root=B/'stage'/str(n);(root/'client/src/vite-env.d.ts').write_text('/// <reference types="vite/client" />\n')
 if n>=65:
  p=root/'server/package.json';d=json.loads(p.read_text());d['scripts']['start']='node dist/src/server.js';p.write_text(json.dumps(d,indent=2)+'\n')
  p=root/'server/scripts/database.ts';s=p.read_text().replace('try {','async function main() {\ntry {')+'\n}\nmain().catch(error=>{console.error(error);process.exitCode=1;});\n';p.write_text(s)
p=B/'stage/63/server/src/routes/chatRoutes.ts';p.write_text(p.read_text().replace('.whereNull("deleted_at")','.where({is_deleted:false})'))
(B/'stage/62/test/responses.test.ts').write_text('''import {test,before,after} from "node:test";
import assert from "node:assert/strict";
import {database,request} from "./database.js";
let h:Awaited<ReturnType<typeof database>>;
before(async()=>{h=await database();await h.db("users").insert({id:1,email:"learner@example.com",display_name:"Learner"});});after(async()=>{if(h)await h.close();});
const api=(path:string,method="GET",body?:unknown)=>request(h.origin,"/api"+path,method,body);
async function survey(token:string,extra:object={}) {return (await h.db("surveys").insert({user_id:1,title:token,status:"active",public_token:token,...extra}).returning("*"))[0];}
test("typed choices reject invalid answers without creating a response",async()=>{const s=await survey("choices");const [q]=await h.db("questions").insert({survey_id:s.id,title:"Language",question_type:"multi_choice",is_required:true,sort_order:1}).returning("*");await h.db("question_options").insert({question_id:q.id,label:"JavaScript",sort_order:1});for(const value of [[],["Unknown"],{},true])assert.equal((await api("/public/surveys/choices/responses","POST",{answers:{[q.id]:value}})).status,400);assert.equal(Number((await h.db("responses").count("* as n").first()).n),0);const r=await api("/public/surveys/choices/responses","POST",{answers:{[q.id]:["JavaScript","JavaScript"]}});assert.equal(r.status,201,JSON.stringify(r.data));assert.equal((await h.db("response_answers").first()).selected_option_ids.length,1);});
test("simultaneous respondents cannot exceed the last available slot",async()=>{const s=await survey("capacity",{max_responses:1});const results=await Promise.all([1,2].map(()=>api("/public/surveys/capacity/responses","POST",{answers:{}})));assert.deepEqual(results.map(r=>r.status).sort(),[201,400]);assert.equal((await h.db("surveys").where({id:s.id}).first()).response_count,1);});
test("date windows and closed state reject responses, optional blank rating remains null",async()=>{await survey("future",{start_date:"2099-01-01"});await survey("expired",{end_date:"2000-01-01"});await survey("closed",{status:"closed"});for(const token of ["future","expired","closed"])assert.equal((await api(`/public/surveys/${token}/responses`,"POST",{answers:{}})).status,400);const s=await survey("rating");const [q]=await h.db("questions").insert({survey_id:s.id,title:"Score",question_type:"rating",is_required:false,sort_order:1,config:{min:1,max:5}}).returning("*");assert.equal((await api("/public/surveys/rating/responses","POST",{answers:{[q.id]:9}})).status,400);assert.equal((await api("/public/surveys/rating/responses","POST",{answers:{[q.id]:""}})).status,201);assert.equal((await h.db("response_answers").where({question_id:q.id}).first()).rating_value,null);});
''')
(B/'stage/63/test/membership.test.ts').write_text('''import {test,before,after} from "node:test";
import assert from "node:assert/strict";
import {database,request} from "./database.js";
let h:Awaited<ReturnType<typeof database>>,room:number,message:number,foreign:number;
before(async()=>{h=await database();await h.db("users").insert([1,2,3].map(id=>({id,username:"user"+id,email:`u${id}@example.com`,password_hash:"demo",display_name:"User "+id})));room=(await h.db("conversations").insert({type:"group",name:"Study",created_by:1}).returning("id"))[0].id;await h.db("conversation_members").insert([{conversation_id:room,user_id:1,role:"admin"},{conversation_id:room,user_id:2,role:"member"}]);message=(await h.db("messages").insert({conversation_id:room,user_id:1,content:"Hello"}).returning("id"))[0].id;const other=(await h.db("conversations").insert({type:"group",name:"Other",created_by:3}).returning("id"))[0].id;foreign=(await h.db("messages").insert({conversation_id:other,user_id:3,content:"Private"}).returning("id"))[0].id;});after(async()=>{if(h)await h.close();});
const api=(path:string,method="GET",body?:unknown,user=1)=>request(h.origin,"/api"+path,method,body,{"x-demo-user-id":String(user)});
test("outsiders cannot read history, poll, react, type, or change membership",async()=>{for(const [path,method,body] of [[`/conversations/${room}/messages`,"GET",undefined],[`/conversations/${room}/messages/new`,"GET",undefined],[`/messages/${message}/reactions`,"POST",{emoji:"+1"}],[`/conversations/${room}/typing`,"POST",{}],[`/conversations/${room}/members`,"POST",{userId:3}]] as const)assert.equal((await api(path,method,body,3)).status,404);assert.equal(Number((await h.db("reactions").count("* as n").first()).n),0);});
test("members can read and react but only admins manage membership",async()=>{assert.equal((await api(`/conversations/${room}/messages`,"GET",undefined,2)).status,200);assert.equal((await api(`/messages/${message}/reactions`,"POST",{emoji:"+1"},2)).status,201);assert.equal((await api(`/conversations/${room}/members`,"POST",{userId:3},2)).status,400);assert.equal((await api(`/conversations/${room}/read`,"POST",{messageId:foreign},2)).status,400);assert.equal((await api(`/conversations/${room}/read`,"POST",{messageId:message},2)).status,200);});
test("owned message CRUD and deduplicated group membership still work",async()=>{const r=await api(`/conversations/${room}/messages`,"POST",{content:"Draft"});assert.equal(r.status,201,JSON.stringify(r.data));const id=r.data.data.id;assert.equal((await api(`/messages/${id}`,"PUT",{content:"Edited"})).status,200);assert.equal((await api(`/messages/${id}`,"PUT",{content:"Other"},2)).status,404);assert.equal((await api(`/messages/${id}`,"DELETE")).status,200);assert.equal((await api(`/messages/${id}`,"PUT",{content:"Revived"})).status,404);assert.equal((await api("/conversations/group","POST",{name:"Group",memberIds:[1,2,2]})).status,201);});
''')
